  k ≤ n → n.choose k = n.factorial / (k.factorial * (n - k).factorial)
@Nat.choose_mul_factorial_mul_factorial : ∀ {n k : ℕ},
  k ≤ n → n.choose k * k.factorial * (n - k).factorial = n.factorial
@Nat.Prime.dvd_factorial : ∀ {n p : ℕ}, Nat.Prime p → (p ∣ n.factorial ↔ p ≤ n)
